//! Cross-implementation parity: the Rust provider and orchestrator must
//! produce byte-identical results to the TypeScript implementation for
//! identical queries against the same database.
//!
//! `ts-parity.db` and `ts-parity.json` are generated by
//! `tests/fixtures/generate-parity-fixtures.mjs` from the built TS packages
//! with `Date.now()` pinned; this test replays every case through the Rust
//! implementation with the same pinned clock and compares the JSON output.
//!
//! The TypeScript implementation was retired after Phase 4 of the Rust port
//! (PORT-005), so these are frozen golden fixtures that still guard ranking
//! parity (regenerating them would require the retired TS packages).
//!
//! Search cases replay in advanced query mode, because the TS provider passed
//! the query to FTS5 unchanged. Plain one-word cases are also replayed in the
//! default literal mode. The one deliberate divergence is the malformed-query
//! case: TS returned an empty result, and Rust now reports
//! `ProviderError::InvalidQuery` (GH-311).
//!
//! If ranking changes on purpose, hand-edit the affected expected entries in
//! `ts-parity.json` in the same PR, explain the diff in the PR description, and
//! record it in ENGINEERING-HISTORY. Ranking changes are discuss-first (see
//! CONTRIBUTING).

use std::path::PathBuf;

use kindling_provider::{retrieve_at, LocalFtsProvider, ProviderError, RetrievalProvider};
use kindling_store::{SqliteKindlingStore, StoreOptions};
use kindling_types::{ProviderSearchOptions, QueryMode, RetrieveOptions, Timestamp};
use serde_json::Value;

fn fixture_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

fn load_fixture() -> (SqliteKindlingStore, Value) {
    let store = SqliteKindlingStore::open_with_options(
        &fixture_path("ts-parity.db"),
        &StoreOptions { readonly: true },
    )
    .expect("fixture database should open read-only");
    let json = std::fs::read_to_string(fixture_path("ts-parity.json"))
        .expect("fixture json should be readable");
    let fixture: Value = serde_json::from_str(&json).expect("fixture json should parse");
    (store, fixture)
}

#[test]
fn search_results_match_ts_provider() {
    let (store, fixture) = load_fixture();
    let now = fixture["now"].as_i64().expect("fixture now") as Timestamp;
    let provider = LocalFtsProvider::from_store(&store);

    let cases = fixture["searchCases"].as_array().expect("searchCases");
    assert!(
        !cases.is_empty(),
        "searchCases fixture must contain at least one case"
    );
    for case in cases {
        let name = case["name"].as_str().unwrap_or("?");
        let fixture_options: ProviderSearchOptions =
            serde_json::from_value(case["options"].clone()).expect("case options should parse");
        assert_eq!(
            fixture_options.query_mode, None,
            "fixtures predate query modes"
        );

        // The TS provider passed the query to FTS5 unchanged, which is
        // advanced mode now (GH-311).
        let options = ProviderSearchOptions {
            query_mode: Some(QueryMode::Advanced),
            ..fixture_options.clone()
        };

        // Deliberate divergence (GH-311): TS swallowed FTS5 syntax errors into
        // an empty result; a malformed advanced query is now an error.
        if name == "malformed query" {
            let err = provider
                .search(&options, now)
                .expect_err("a malformed advanced query must be rejected");
            assert!(
                matches!(err, ProviderError::InvalidQuery(_)),
                "expected InvalidQuery, got {err:?}"
            );
            assert_eq!(case["expected"], Value::Array(Vec::new()));
            continue;
        }

        let results = provider
            .search(&options, now)
            .unwrap_or_else(|err| panic!("search case {name:?} failed: {err}"));
        let actual = serde_json::to_value(&results).expect("results should serialize");

        assert_eq!(
            actual,
            case["expected"],
            "search case {name:?} diverged from the TS provider\nactual: {}\nexpected: {}",
            serde_json::to_string_pretty(&actual).unwrap(),
            serde_json::to_string_pretty(&case["expected"]).unwrap(),
        );

        // A single plain word means the same in both modes, so the default
        // (literal) mode must reproduce these cases too.
        if fixture_options.query.chars().all(char::is_alphanumeric) {
            let literal = provider
                .search(&fixture_options, now)
                .unwrap_or_else(|err| panic!("literal search case {name:?} failed: {err}"));
            assert_eq!(
                serde_json::to_value(&literal).expect("results should serialize"),
                case["expected"],
                "literal search case {name:?} diverged from the TS provider",
            );
        }
    }
}

#[test]
fn retrieve_results_match_ts_orchestrator() {
    let (store, fixture) = load_fixture();
    let now = fixture["now"].as_i64().expect("fixture now") as Timestamp;
    let provider = LocalFtsProvider::from_store(&store);

    let cases = fixture["retrieveCases"].as_array().expect("retrieveCases");
    assert!(
        !cases.is_empty(),
        "retrieveCases fixture must contain at least one case"
    );
    for case in cases {
        let name = case["name"].as_str().unwrap_or("?");
        let options: RetrieveOptions =
            serde_json::from_value(case["options"].clone()).expect("case options should parse");

        let result = retrieve_at(&store, &provider, &options, now)
            .unwrap_or_else(|err| panic!("retrieve case {name:?} failed: {err}"));
        let actual = serde_json::to_value(&result).expect("result should serialize");

        assert_eq!(
            actual,
            case["expected"],
            "retrieve case {name:?} diverged from the TS orchestrator\nactual: {}\nexpected: {}",
            serde_json::to_string_pretty(&actual).unwrap(),
            serde_json::to_string_pretty(&case["expected"]).unwrap(),
        );
    }
}
